mapper.update:
UPDATE byai_group_chat_turn
SET status = 'SUCCEEDED', answer_message_id = COALESCE(#{answerMessageId}, answer_message_id), finish_time = #{now}
WHERE execution_id = #{executionId} AND status = 'RUNNING'

UPDATE byai_group_chat_turn
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage}, finish_time = #{now}
WHERE execution_id = #{executionId} AND status IN ('RUNNING', 'QUEUED')

mapper.select:
SELECT  FROM byai_group_chat_turn
WHERE answer_message_id = #{messageId} OR ack_message_id = #{messageId}
    OR trigger_message_id = #{messageId} ORDER BY execution_id LIMIT 1

SELECT * FROM byai_group_chat_execution WHERE root_message_id = #{rootId}
AND target_agent_id = #{agentId} AND initiator_user_id = #{userId}
ORDER BY execution_id DESC LIMIT 1

SELECT q.execution_id, q.candidate_session_id, q.trace_id
FROM byai_group_chat_turn q
WHERE q.status = 'QUEUED' AND q.execution_id > #{afterId}
  AND NOT EXISTS (
      SELECT 1 FROM byai_group_chat_turn older
      WHERE older.candidate_session_id = q.candidate_session_id
        AND older.status = 'QUEUED' AND older.execution_id < q.execution_id
  )
ORDER BY q.execution_id ASC
LIMIT #{limit}

SELECT q.execution_id, q.candidate_session_id, q.trace_id
FROM byai_group_chat_turn q
WHERE q.status = 'RUNNING' AND q.execution_id > #{afterId}
  AND q.trace_id IS NULL
ORDER BY q.execution_id ASC
LIMIT #{limit}

SELECT q.execution_id, q.candidate_session_id, q.trace_id
FROM byai_group_chat_turn q
WHERE q.status = 'RUNNING' AND q.execution_id > #{afterId}
  AND q.trace_id IS NOT NULL
ORDER BY q.execution_id ASC
LIMIT #{limit}
